                          <td class="py-2 px-2 truncate max-w-[150px]">${aAAA ? `<span class="font-sans font-semibold">${aAAA.full_name}</span> <span class="text-emerald-400">(${aAAA.record_str})</span>` : '<span class="bnn-muted">—</span>'}</td>
